                                @Valid @RequestBody UpdateWorkBlockRequest request) {
        return service.update(workKey, request);
    }

    /** 取消未开始施工单（已开始不可取消，立即释放并保留不可变取消记录）。 */
    @PostMapping("/{workKey}/cancel")
