                                @Valid @RequestBody CancelWorkBlockRequest request) {
        return service.cancel(workKey, request);
    }

    /** 查询单个施工窗口。 */
    @GetMapping("/{workKey}")
    public WorkBlockView get(@PathVariable String workKey) {
